//! ✖️ Actual original cancellation aliases retain their real output before an independently refused source receipt.
use semio_framework_job_context::testkit;
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[test]
fn actual_cancel_alias_output_survives_refused_receipt_with_exact_child_work(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let s=&law["source"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7527),Generation(7),stock,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut alias=None;
 for row in law["cases"].as_array().unwrap(){let denied=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,maximum_depth:row["depth"].as_u64().unwrap()as usize,..stock};caller.turn(denied,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let(result,heap)=observe(||cx.admit_original_cancel_alias(&mut alias));assert!(!result?);assert!(alias.is_none());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();}
 caller.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let(result,heap)=testkit::with_retained_receipt_policy(cx,|cx|{testkit::set_cancel_receipt_refusal(true);observe(||cx.admit_original_cancel_alias(&mut alias))});let failure=result.unwrap_err();assert!(failure.primary_value().is_some());assert_eq!(failure.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(alias.as_ref().unwrap().is_same_node(cx.original_cancel_token()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress().copied_items,before.copied_items+1);assert_eq!(cx.original_work_units_spent()-work,1);Ok(())}).unwrap();
 caller.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(cx.admit_original_cancel_alias(&mut alias)?);assert!(alias.as_ref().unwrap().is_same_node(cx.original_cancel_token()));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();caller.return_alias(alias.take().unwrap(),stock);caller.cancel().cancel_now();caller.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(!cx.admit_original_cancel_alias(&mut alias)?);assert!(alias.is_none());assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();caller.retire(stock);
}
